/** @param {string} slug */
export function getArticle(slug) {
  return ARTICLES.find((a) => a.slug === slug) || null;
}

export const UPCOMING_EVENTS = EVENTS.filter((e) => !e.isPast);
export const PAST_EVENTS = EVENTS.filter((e) => e.isPast);
